use vstd::prelude::*;

verus! {

spec fn rev_index(n: nat, j: nat) -> nat {
    // for j < n, maps j to the corresponding index in the reversed array
    (n - 1 - j)
}

fn reverse(a: &Vec<i32>) -> (a_rev: Vec<i32>)
    ensures
        a_rev.len() == a.len(),
        forall|j: int|
            0 <= j < a.len() ==> a_rev[j] == a[rev_index(a.len() as nat, j as nat) as int],
{
    let n = a.len();
    let mut a_rev = Vec::with_capacity(n);

    for i in (0..n).rev()
        invariant
            a_rev.len() <= n,
            a_rev.len() == n - (i + 1),
            forall|j: int|
                0 <= j < a_rev.len() ==>
                    a_rev[j] == a[rev_index(n as nat, j as nat) as int],
        decreases i,
    {
        // When pushing a[i], it should become the next element of the reverse.
        assert(a_rev.len() < n);
        assert(rev_index(n as nat, a_rev.len() as nat) == i as nat) by {
            // a_rev.len() == n - (i+1)  ==>  n-1-a_rev.len() == i
            // i.e., rev_index(n, len) == i
        };

        a_rev.push(a[i]);

        assert(a_rev[a_rev.len() as int - 1] == a[i as int]);
        assert(
            forall|j: int|
                0 <= j < a_rev.len() ==>
                    a_rev[j] == a[rev_index(n as nat, j as nat) as int]
        );
    }

    a_rev
}

} // verus!

